export function g10ScienceYearLessons(): LessonSeed[] {
  return G10_SCIENCE_LESSONS.map((L) => ({
    title: L.title,
    description: L.description,
    objectives: L.objectives,
    content: L.content,
    order: L.order,
    durationMin: L.durationMin,
    sectionKey: L.sectionKey,
    questions: L.questions,
    topicMeta: {
      title: L.title,
      focus: L.description,
      keyIdeas: L.objectives.split("\n").map((s) => s.replace(/^•\s*/, "").trim()).filter(Boolean),
      practice: [
        { q: "Central aim of this lesson?", a: L.description },
        { q: "What should a strong solution include?", a: "A labeled model, evidence, and a revised explanation when needed." },
      ],
    },
  }));
}

export function g10ScienceUnitLabel(sectionKey: string): string | null {
  const m = /^unit-(\d+)$/.exec(sectionKey);
  if (!m) return null;
  const n = Number(m[1]);
  const meta = G10_SCIENCE_UNIT_META.find((u) => u.n === n);
  if (!meta) return null;
  return `Unit ${meta.n} of 10 · ${meta.title}`;
}
